+            reason: `It pairs with more of your closet than anything else you're missing.`,
+          }
+        }
+        entitlements={{
+          analytics: entitlements.analytics,
+          gapAnalysis: entitlements.gapAnalysis,
+        }}
+        isPro={entitlements.tier === "pro"}
+      />
+      <MobileNav />
+    </div>
