import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { MobileNav } from "@/components/shell/mobile-nav";
import { localDateFor } from "@/lib/outfits/local-date";
import { currentStreak } from "@/lib/diary/streak";
import { initials, handleFrom, paletteFor } from "@/lib/profile/identity";
import { ProfileHub, type HubLink } from "@/components/profile/profile-hub";
import { entitlementsFor } from "@/lib/billing/tiers";

/**
 * Rows are marked ready ONLY for routes that exist on `main` today.
 *
 * Two of the four bottom tabs used to 404 for exactly this reason (BUGS.md #5);
 * an unready row renders disabled with "Soon" rather than linking into nothing.
 */
const LINKS: HubLink[] = [
  { href: "/style-dna", label: "Style DNA", desc: "Your archetype, shareable", icon: "dna", ready: false },
  { href: "/outfits", label: "Saved Outfits", desc: "Looks you kept", icon: "saved", ready: false },
  { href: "/stats", label: "Wear Stats", desc: "What you actually wear", icon: "stats", ready: true },
  { href: "/settings", label: "Settings", desc: "Preferences and account", icon: "settings", ready: true },
];

export default async function ProfilePage() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) redirect("/");

  const { data: profile } = await supabase
    .from("profiles")
    .select("display_name, archetype, tier, location_timezone")
    .eq("id", user.id)
    .single();

  /**
   * `outfits` counts looks WORN, not looks generated.
   *
   * The `outfits` table holds every look the generator ever produced — three
   * per drop, plus styled looks, plus every past day — so a row count reports
   * the generator's output rather than anything the user did, and it inflates
   * on its own every day the app runs.
   */
  const [{ count: pieces }, { data: logs }] = await Promise.all([
    supabase.from("items").select("id", { count: "exact", head: true }).eq("archived", false),
    supabase.from("wear_logs").select("worn_on").eq("user_id", user.id),
  ]);

  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
  const wornDates = (logs ?? []).map((r) => r.worn_on);

  return (
    <div className="flex min-h-dvh flex-1 flex-col">
      <ProfileHub
        name={profile?.display_name ?? "You"}
        handle={handleFrom(user.email ?? "")}
        initials={initials(profile?.display_name ?? null, user.email ?? "")}
        archetype={profile?.archetype ?? null}
        palette={paletteFor(profile?.archetype ?? null)}
        tier={entitlementsFor(profile?.tier).tier}
        stats={{
          pieces: pieces ?? 0,
          outfits: wornDates.length,
          streak: currentStreak(wornDates, today),
        }}
        links={LINKS}
      />
      <MobileNav />
    </div>
  );
}

import { formatMoney } from "@/lib/format/money";
import { daysBetween } from "@/lib/format/days";

/**
 * The aggregates behind `/stats` (Fitcheck.dc.html:737-780).
 *
 * Pure functions over rows the caller has already fetched — no Supabase here,
 * so every number on that screen is testable without a database. There is no AI
 * call anywhere on this screen, including the gap analysis (see ./gap.ts).
 */

type PricedItem = { id: string; price: number | null };

/**
 * `price` is nullable and most closets are mostly null: the tagger cannot read
 * a price off a photograph, so it is only ever there because the user typed it.
 * Every total therefore has to mean "of the pieces we know about", and the
 * screen has to be honest that it is not the whole wardrobe.
 */
export function closetStats(
  items: PricedItem[],
  logs: { item_id: string }[],
): { value: string; totalWears: number; avgCostPerWear: string | null } {
  const total = items.reduce((sum, i) => sum + (i.price ?? 0), 0);
  const totalWears = logs.length;
  return {
    value: formatMoney(total),
    totalWears,
    // Null rather than 0 or "€0.00" on either empty branch. Dividing by zero
    // wears prints €Infinity, and €0.00 for an unpriced closet states something
    // false — the UI hides the tile instead. Same stance as `itemWearStats`.
    avgCostPerWear: totalWears > 0 && total > 0 ? formatMoney(total / totalWears) : null,
  };
}

/** The n most-worn item ids, highest first. Pieces with no wears are excluded. */
export function mostWorn(items: PricedItem[], wearsById: Record<string, number>, n: number): string[] {
  return items
    .map((i) => ({ id: i.id, wears: wearsById[i.id] ?? 0 }))
    .filter((i) => i.wears > 0)
    .sort((a, b) => b.wears - a.wears)
    .slice(0, n)
    .map((i) => i.id);
}

/**
 * The n longest-idle pieces, with how many days it has been.
 *
 * A never-worn item is the whole point of the section, not a gap in the data —
 * the pieces you never reach for are exactly the ones with no wear rows. They
 * sort FIRST, above anything merely worn a long time ago, because "you have
 * never worn this" is the stronger version of the same statement.
 *
 * ⚠️ `days` is `null` for those, not `Infinity`. Infinity sorts correctly and
 * then reaches the screen as "∞ days ago"; null forces the UI to say "Never
 * worn", which is both true and the more damning line.
 */
export function gatheringDust(
  items: PricedItem[],
  lastWornById: Record<string, string>,
  today: string,
  n: number,
): { id: string; days: number | null }[] {
  return items
    .map((i) => {
      const last = lastWornById[i.id];
      return { id: i.id, days: last ? daysBetween(last, today) : null };
    })
    .sort((a, b) => (b.days ?? Number.POSITIVE_INFINITY) - (a.days ?? Number.POSITIVE_INFINITY))
    .slice(0, n);
}

export type Tier = "free" | "pro";

/** The three things that spend a model request. See docs/MONETISATION.md §2. */
export type GenerationKind = "drop" | "regenerate" | "styled";

export type Entitlements = {
  tier: Tier;
  /**
   * Rerolls per DAY, across all occasions. null = unlimited.
   *
   * Global rather than per-occasion (user decision, 2026-08-05). Most people
   * care about one occasion on a given day, so a per-occasion allowance is
   * strictest exactly where attention goes and generous where nobody is
   * looking: you could be refused a second Work reroll while holding an unused
   * Evening one you never wanted.
   *
   * The usual objection to a global pool — that it can block an occasion you
   * have not opened yet — does not apply here, because a drop is free on every
   * tier. Tapping a new occasion is always a drop, so the pool only ever meters
   * rerolls.
   */
  regeneratesPerDay: number | null;
  /**
   * How many pieces a closet may hold. null = unlimited.
   *
   * Counts UNARCHIVED items only. Archiving is the user's way to make room —
   * there is no delete path in the product, so counting archived pieces would
   * strand a user at the cap with no way out. It also matches what the number
   * claims: an archived piece is not in your closet.
   *
   * 50 is deliberately well clear of the ~20-30 range where combo coverage
   * thins (PR #15 measured a 21-item closet at 21 combos in winter against 48
   * in summer), so the free tier never experiences a starved stylist — it
   * experiences a full one, with a ceiling.
   */
  closetItems: number | null;
  /** "Style an outfit with this" — Pro #2. */
  styledLooks: boolean;
  savedOutfits: number | null;
  /** The Wear Stats SCREEN. The per-item tile on item detail is free. */
  analytics: boolean;
  gapAnalysis: boolean;
  packingMode: boolean;
};

/**
 * The tiers, as data. See docs/MONETISATION.md for the reasoning — in short:
 * meter what costs us money, sell what compounds, and never gate the daily
 * drop, the share card, or the closet.
 *
 * The free ceiling is four occasion drops plus three rerolls = 7 generations a
 * day, about $0.63/month at $0.003 each and nearer $0.20 in realistic use.
 * **The ceiling is the point** — a free tier needs a worst case you can
 * survive, and this one cannot be raised by adding clothes.
 */
export const FREE: Entitlements = {
  tier: "free",
  regeneratesPerDay: 3,
  closetItems: 50,
  styledLooks: false,
  savedOutfits: 10,
  analytics: false,
  gapAnalysis: false,
  packingMode: false,
};

export const PRO: Entitlements = {
  tier: "pro",
  regeneratesPerDay: null,
  closetItems: null,
  styledLooks: true,
  savedOutfits: null,
  analytics: true,
  gapAnalysis: true,
  packingMode: true,
};

// The pure functions live HERE, not in entitlements.ts, so tests can import them
// without dragging in `server-only` (which does not resolve under jsdom).
// entitlements.ts re-exports them for app code.

/** Unknown input resolves to free: capabilities fail CLOSED. */
export function entitlementsFor(tier: unknown): Entitlements {
  return tier === "pro" ? PRO : FREE;
}

export type GenerationCheck = {
  allowed: boolean;
  /** null = unlimited. Only meaningful for a metered kind. */
  remaining: number | null;
  reason?: string;
};

/**
 * May this user spend a model request right now?
 *
 * `regeneratesUsed` is the user's total reroll count for their local today,
 * across every occasion.
 *
 * A drop is never metered on any tier: MONETISATION §1 and Decision 4 both say
 * the daily drop is the product, and rationing it is how nobody discovers the
 * magic. That is also what makes a global reroll pool safe — a user can always
 * open any occasion, so the pool can never strand them.
 */
export function checkGeneration(
  e: Entitlements,
  input: { kind: GenerationKind; regeneratesUsed: number },
): GenerationCheck {
  if (input.kind === "drop") return { allowed: true, remaining: null };

  if (input.kind === "styled") {
    return e.styledLooks
      ? { allowed: true, remaining: null }
      : {
          allowed: false,
          remaining: 0,
          reason: "Building a look around a piece is a Pro feature.",
        };
  }

  if (e.regeneratesPerDay == null) return { allowed: true, remaining: null };
  const remaining = Math.max(0, e.regeneratesPerDay - input.regeneratesUsed);
  return remaining > 0
    ? { allowed: true, remaining }
    : {
        allowed: false,
        remaining: 0,
        reason: `That's your ${e.regeneratesPerDay} rerolls for today. Pro rerolls without limit.`,
      };
}

/**
 * May this user add another piece?
 *
 * `held` is the number of UNARCHIVED pieces already in the closet — archiving
 * is how a free user makes room, since nothing in the product deletes an item.
 */
export function checkCloset(e: Entitlements, held: number): GenerationCheck {
  if (e.closetItems == null) return { allowed: true, remaining: null };
  const remaining = Math.max(0, e.closetItems - held);
  return remaining > 0
    ? { allowed: true, remaining }
    : {
        allowed: false,
        remaining: 0,
        reason: `A free closet holds ${e.closetItems} pieces. Pro is unlimited — or archive something you no longer wear.`,
      };
}
